-- Supplier extranet: read-only contract and rate-plan summaries (ADR 0061, slice 1).
-- Adds one permission only. No table, column or grant changes: the API runtime role already reads Contract,
-- RatePlan, RoomType, BoardBasis and SupplierHotelMapping. The route filters by tenant and the caller's supplier.
--
-- Tenant-index review: contracts are read by (tenant_id, supplier_id); the existing Contract tenant/supplier
-- indexes cover this, and the page is capped at 200 rows.
--
-- Rollback is a later forward migration. Do not edit this file after it is applied.
--   DELETE FROM "Permission" WHERE "key" = 'supplier.extranet.contracts.read';
-- (Remove role assignments of that permission first.)

INSERT INTO "Permission" ("id", "key", "description") VALUES
  ('perm_supplier_extranet_contracts_read', 'supplier.extranet.contracts.read', 'Read contract and rate-plan summaries of the authenticated supplier organization')
ON CONFLICT ("key") DO UPDATE SET "description" = EXCLUDED."description";
